The graph of $y=g(x)$ is shown. Evaluate (a) $g(1)$ and (b) $g(-1)+g(1)$.
[tikz]
\begin{tikzpicture}[x=7mm,y=7mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\draw[black,->] (-3.5,0)--(3.5,0);
\draw[black,->] (0,-1)--(0,5.5);
\path (3.5,0) node[right] {$x$} (0,5.5) node[above] {$y$};
\foreach \x in {-3,-2,-1,1,2,3}{\draw[black] (\x,-0.08)--(\x,0.08);\path (\x,-0.08) node[below,font=\fontsize{8.5}{10}\selectfont] {$\x$};}
\foreach \y in {1,2,3,4,5}{\draw[black] (-0.08,\y)--(0.08,\y);\path (-0.08,\y) node[left,font=\fontsize{8.5}{10}\selectfont] {$\y$};}
\path (0,0) node[below left,font=\fontsize{8.5}{10}\selectfont] {$0$};
\draw[black,thick,<-] (-3,5)--(1,1);
\draw[black,fill=white] (1,1) circle[radius=2pt];
\draw[black,thick,->] (1,4)--(3,4);
\fill[black] (1,4) circle[radius=2pt];
\end{tikzpicture}
[/tikz]
